import { describe, expect, it } from 'vitest'

import {
  auditFacetQuery,
  auditFacetsInfiniteOptions,
  auditListQuery,
  serializeSearchHints,
} from './audit'

/** The serialized query as its own key/value view; the generated key type is regenerated by the API owner. */
function wire(query: object): Record<string, unknown> {
  return query as Record<string, unknown>
}

describe('audit search hints serialization', () => {
  it('stops facet continuation when the server exhausts its offset budget', () => {
    const options = auditFacetsInfiniteOptions({ facetColumn: 'created_at', facetLimit: 50 })
    const last = {
      hasMore: false,
      values: Array.from({ length: 50 }, (_, index) => ({
        value: `value-${index}`,
        label: `value-${index}`,
        count: 1,
      })),
    }
    expect(options.getNextPageParam?.(last, [last], 10000, [10000])).toBeUndefined()
    expect(options.getNextPageParam?.({ ...last, hasMore: true }, [last], 9950, [9950])).toBe(10000)
  })
  it('sends response enrichment only on list queries, never on strict facet queries', () => {
    expect(auditListQuery({ includeAssistant: true })).toHaveProperty('includeAssistant', true)
    expect(auditFacetQuery({ facetColumn: 'actor', includeAssistant: true })).not.toHaveProperty(
      'includeAssistant',
    )
  })
  it('serializes one JSON searchHints object and no scalar hint fields', () => {
    const query = wire(
      auditListQuery({
        search: 'Failed',
        searchHints: {
          actionKinds: ['iam.session.login'],
          resultKinds: ['failed'],
          actorNull: true,
          createdAtRange: { min: '2026-08-09T10:00:00.000Z', max: '2026-08-09T10:00:01.000Z' },
        },
      }),
    )

    expect(query.search).toBe('Failed')
    expect(JSON.parse(query.searchHints as string)).toEqual({
      actionKinds: ['iam.session.login'],
      resultKinds: ['failed'],
      actorNull: true,
      createdAtRange: { min: '2026-08-09T10:00:00.000Z', max: '2026-08-09T10:00:01.000Z' },
    })
    for (const stale of [
      'searchActionKind',
      'searchSurfaceKind',
      'searchResultKind',
      'searchActorNull',
      'searchCreatedAtFrom',
      'searchCreatedAtTo',
    ]) {
      expect(query).not.toHaveProperty(stale)
    }
  })

  it('omits searchHints entirely when nothing was derived', () => {
    expect(serializeSearchHints(undefined)).toBeUndefined()
    expect(serializeSearchHints({})).toBeUndefined()
    expect(wire(auditListQuery({ search: 'plain' }))).not.toHaveProperty('searchHints')
  })

  it('keeps the global hints and the facet-local hints in separate JSON parameters', () => {
    const query = wire(
      auditFacetQuery({
        facetColumn: 'result',
        search: 'Failed',
        searchHints: { actionKinds: ['iam.session.login'] },
        facetSearch: 'rej',
        facetSearchHints: { resultKinds: ['rejected'] },
      }),
    )

    // The global term's hints narrow only the whole-table vocabulary.
    expect(JSON.parse(query.searchHints as string)).toEqual({
      actionKinds: ['iam.session.login'],
    })
    // The opened column's own search resolves against that column only.
    expect(JSON.parse(query.facetSearchHints as string)).toEqual({ resultKinds: ['rejected'] })
    expect(query.facetSearch).toBe('rej')
    expect(query).not.toHaveProperty('searchResultKind')
  })
})
